// Final Project JavaScript Code (or combine HTML+JS)
const tasks = [
  { id: 1, title: 'Complete DOM Module', completed: true },
  { id: 2, title: 'Build JS Final Project', completed: false }
];

function addTask(title) {
  if (!title || title.trim() === '') return false;
  tasks.push({ id: Date.now(), title: title.trim(), completed: false });
  return true;
}

console.log('Total tasks:', tasks.length);
